// ---- Event delegation for todo list ----
// Toggle checkbox via 'change' event (fires after the browser commits the checked state).
// Using 'click' causes race conditions with Cypress chain commands in a real browser
// because the native checkbox activation fires additional events after 'click' that
// Cypress detects as a page update, detaching the chained subject.
todoList.addEventListener('change', function (e) {
  if (e.target.classList.contains('toggle')) {
